// SPDX-License-Identifier: AGPL-3.0-or-later  ·  Copyright (c) 2026 John Chen
// ROOFS by style name. The model picks a style and a few options; the tool builds a skilled roof: correct stair
// facing, half and corner shapes at hips and valleys, closed steep faces, gable walls, verges, eaves (plain, flared,
// cornice with dentils), ridge caps or crests, dormers, a classical pediment, chimneys and a tower, over a rectangle or
// a union of rectangles (L, T, U plans). Under the roof stays hollow (an attic).
//
//   roof(g, footprint, style, opts)   footprint: [x0,z0,x1,z1] | [[x0,z0,x1,z1], ...] | {from,to}; opts.y = eave course
//   reroof(g, opts)                   on an existing build: detect the eave and footprint, strip the old roof, build anew
//   detectEave(g, opts)               just the detection: { eave, y, footprint, rects, area }
//
// How it works: every style is a HEIGHT FUNCTION over the footprint (dilated by the overhang): hip = Chebyshev
// distance to the edge (so any rectilinear plan gets true hips and valleys), gable = distance to the long walls per
// wing (cross-gables meet in valleys), mansard and gambrel = two pitches, dutch gable = hip below a set-back gablet,
// shed = one slope. One rasterizer turns heights (in half blocks) into blocks: slabs for half steps, stairs facing
// uphill (outer_* on hips, inner_* in valleys), full blocks to close steep faces, ridge blocks where slopes meet.
// Stairs `facing` = the side of the full-height back (uphill); outer_left / inner_left = the extra quarter on the
// counter-clockwise side of `facing` seen from above (same convention as shapes-massing.mjs).
import { functionalCells } from "./check.mjs";
import { colourOf, toneDistance, visible } from "./families.mjs";
import { textureOf, ROOF_PALETTES } from "./roof-texture.mjs";
import { reviewRoof, ratioCap } from "./roof-review.mjs";
import { roofForm } from "./roof-forms.mjs";            // the ESM cycle (roof-forms imports roof) is safe: nothing runs at module evaluation
import { upturn } from "./roof-eaves.mjs";
import { applyPresets } from "./roof-presets.mjs";

export const FORM_STYLES = ["cone", "dome", "onion", "tiered", "sawtooth"];          // built by roof-forms.mjs
export const ROOF_STYLES = ["gable", "hip", "pyramid", "mansard", "gambrel", "flat-parapet", "shed", "dutch-gable", ...FORM_STYLES];
export const PITCHES = { half: 0.5, 45: 1, steep: 2, "very-steep": 3 };
const CARD = ["north", "south", "east", "west"];
const DIR = { north: [0, -1], south: [0, 1], west: [-1, 0], east: [1, 0] };
const OPP = { north: "south", south: "north", east: "west", west: "east" };
const CCW = { north: "west", west: "south", south: "east", east: "north" };
const ZD = new Set(["north", "south"]);
const K = (x, z) => `${x},${z}`;
const XZ = (k) => k.split(",").map(Number);
const step = (x, z, d) => [x + DIR[d][0], z + DIR[d][1]];
const strip = (n) => String(n).replace(/^minecraft:/, "");
const AIR = /(^|:)(cave_|void_)?air$/;

// ---- materials ----------------------------------------------------------------------------------------------------
const WOODS = new Set(["oak", "spruce", "birch", "jungle", "acacia", "dark_oak", "mangrove", "cherry", "bamboo", "crimson", "warped", "pale_oak"]);
/** A material by any name ("deepslate_tiles", "deepslate_tile", "spruce", "stone_brick_stairs") -> its forms. */
export function materialOf(name) {
  let n = strip(name).replace(/_(stairs|slab|wall)$/, "");
  n = n.replace(/^(waxed_)?(exposed_|weathered_|oxidized_)?copper(_block)?$/, (_, w = "", e = "") => `${w}${e}cut_copper`);   // only cut copper has stairs and slabs
  const full = { quartz: "quartz_block", purpur: "purpur_block", smooth_quartz: "smooth_quartz" }[n] || (WOODS.has(n) ? `${n}_planks` : /(brick|tile)$/.test(n) ? `${n}s` : n);
  let p = n.replace(/_planks$/, "").replace(/(brick|tile)s$/, "$1").replace(/^(quartz|purpur)_block$/, "$1");
  return { prefix: p, full: n === p ? full : n, stairs: `${p}_stairs`, slab: `${p}_slab`, wall: `${p}_wall` };
}
/** Materials that have no stairs or slab forms (a roof of them would place invalid blocks). */
export const NO_STAIRS = /(^|_)(terracotta|concrete|concrete_powder|log|wood|hyphae|stem|glass|wool|dirt|sand|gravel|ice|clay)$/;
const stairs = (m, facing, shape = "straight", half = "bottom") => [m.stairs, { facing, half, shape, waterlogged: "false" }];
const slab = (m, type = "bottom") => [m.slab, { type, waterlogged: "false" }];
const outerStair = (zD, xD) => { const f = OPP[zD], hx = OPP[xD]; return [f, CCW[f] === hx ? "outer_left" : "outer_right"]; };
const innerStair = (hz, hx) => [hz, CCW[hz] === hx ? "inner_left" : "inner_right"];

// ---- footprints ---------------------------------------------------------------------------------------------------
function rectsOf(fp) {
  let r = fp.from ? [[fp.from[0], fp.from[fp.from.length === 3 ? 2 : 1], fp.to[0], fp.to[fp.to.length === 3 ? 2 : 1]]] : typeof fp[0] === "number" ? [fp] : fp;
  return r.map(([a, b, c, d]) => [Math.min(a, c), Math.min(b, d), Math.max(a, c), Math.max(b, d)]);

