export function roof(g, footprint, style = "hip", o = {}) {
  if (ROOF_PRESETS[style] || o.preset) {                                   // a preset: good options by construction, flags override
    const name = ROOF_PRESETS[style] ? style : o.preset, { preset, ...rest } = o;
    if (!ROOF_PRESETS[name]) throw new Error(`roof: unknown preset ${name} (${Object.keys(ROOF_PRESETS).join(", ")})`);
    const p = presetOptions(name, g, rectsOf(footprint), rest);
    return roof(g, footprint, rest.style && ROOF_STYLES.includes(rest.style) ? rest.style : p.style, { ...p, ...Object.fromEntries(Object.entries(rest).filter(([k]) => k !== "style")), _notes: p._notes, _preset: name });
  }
  if (!ROOF_STYLES.includes(style)) throw new Error(`roof: unknown style ${style} (${ROOF_STYLES.join(", ")})`);
  if (o.y == null) throw new Error("roof: opts.y (the eave course: wall top + 1) is required");
  const rects = rectsOf(footprint), y0 = o.y, W = writer(), notes = [...(o._notes || [])];
  let P = pitchOf(o.pitch ?? 45);
  // material: a palette / mix / block becomes a texture (materialAt by role) unless texture:false or the caller brings a hook
  const texSeed = o.seed ?? 0;
  const baseOf = (n) => { const mix = ROOF_PALETTES[n]?.mix ?? (Array.isArray(n) ? n : n?.mix); return mix ? mix.find((m) => m[2] !== "full")[0] : n; };
  const resolve = (n) => {
    if (o.texture === false || o.materialAt || (typeof n === "string" && NO_STAIRS.test(materialOf(n).prefix))) return { tex: null, base: o.texture === false && o.material == null ? "deepslate_tile" : baseOf(n) };   // texture:false with no material is the legacy single block
    try { const tex = textureOf(n, { seed: texSeed }); return { tex, base: tex.members.find((m) => !m.fullOnly).block }; } catch { return { tex: null, base: baseOf(n) }; }
  };
  const given = o.material ?? DEFAULT_MATERIAL;
  let { tex, base } = resolve(given);
  let mat = materialOf(base);
  const trim = materialOf(o.trim ?? base);
  for (const [label, m] of [["material", mat], ["trim", trim]]) if (NO_STAIRS.test(m.prefix)) notes.push(`${label} ${m.prefix} has no stairs or slabs: the roof would place invalid blocks (use a brick, tile, plank, cut-stone or cut-copper material)`);
  const fc = o.protect ?? (() => { const f = functionalCells(g); return new Set([...f.protect.keys(), ...f.keepClear]); })();
  const M0 = maskOf(rects, 0), R0 = largest(rects), wallH = wallHeightOf(g, R0, y0);
  const wallAt = (x, z) => { const b = g.inBounds(x, y0 - 1, z) ? strip(g.blockAt(x, y0 - 1, z)) : null; return b && !AIR.test(b) && !/stairs|slab|glass|pane|door|fence|wall$/.test(b) ? b : null; };
  const tally = new Map();                                                  // the walls' own block, for gables inside the plan
  for (const k of M0) { const [x, z] = XZ(k); if (CARD.some((d) => !M0.has(K(...step(x, z, d))))) { const b = wallAt(x, z); if (b) tally.set(b, (tally.get(b) || 0) + 1); } }
  const mainWall = [...tally].sort((a, b) => b[1] - a[1])[0]?.[0];
  // contrast: a roof must read as a roof, not as more wall (tone measured from the textures, families.mjs)
  const contrast = { checked: o.contrast === false, off: o.contrast === false, distance: null };
  if (o.contrast !== false && mainWall && style !== "flat-parapet") {
    const tone = (m) => { const r = resolve(m), a = r.tex ? r.tex.meanRgb : colourOf(materialOf(r.base).full), b = colourOf(mainWall); return a && b ? toneDistance(a, b) : null; };
    const d0 = tone(given);
    contrast.checked = d0 != null; contrast.distance = d0;
    if (d0 != null && d0 < CONTRAST) {
      const alts = [...(o.alt || []), ...ALT_ROOF].filter((m) => m !== given).map((m) => [m, tone(m)]).filter(([, d]) => d != null);
      const pick = alts.find(([, d]) => d >= CONTRAST) || alts.sort((a, b) => b[1] - a[1])[0];
      if (pick) { notes.push(`roof material ${typeof given === "string" ? given : mat.prefix} too close in tone to the walls (${mainWall}, ${d0.toFixed(2)} < ${CONTRAST}): used ${pick[0]} (contrast: false keeps it)`); ({ tex, base } = resolve(pick[0])); mat = materialOf(base); contrast.distance = pick[1]; }
    }
  }
  const gableBlock = (x, z) => o.gable || wallAt(x, z) || mainWall || mat.full;
  // ---- materials: explicit options win, then the materialAt hook (by role), then the defaults ------------------------
  const hook = tex ? tex.materialAt : o.materialAt, MATS = new Map();
  const heightMod = o.heightMod ?? (o.eave === "upturned" ? upturn() : undefined);
  const fieldRgb = tex ? tex.meanRgb : colourOf(mat.full), edgeBlk = {};
  const edgeTone = (b) => { const c = b && colourOf(materialOf(b).full); return c && fieldRgb ? toneDistance(c, fieldRgb) : null; };
  const matOf = (name) => { let m = MATS.get(name); if (!m) MATS.set(name, (m = materialOf(name))); return m; };
  let courses = 0;
  const hooked = (role, x, z, y, full = false) => { const n = hook ? hook({ x, z, course: Math.max(0, y - y0), courses, role, full }) : null; return n ? matOf(n) : null; };
  const pickMat = (role, x, z, y, fallback, full = false) => hooked(role, x, z, y, full) ?? fallback;
  const review = (facts, extra = {}) => {
    const rev = reviewRoof(facts, { ...o, wallBlock: mainWall, preset: o._preset, ...extra });
    for (const w of rev.warnings) notes.push(`WARN ${w.code}: ${w.message}`);
    return rev;
  };
  if (FORM_STYLES.includes(style)) {                                       // cone / dome / onion / tiered / sawtooth: roof-forms.mjs
    const { preset: _p, texture: _t, ...rest } = o;
    const r = roofForm(g, footprint, style, { ...rest, material: base, trim: o.trim, materialAt: hook, protect: fc, _notes: notes });
    r.facts.preset = o._preset ?? null; r.facts.contrast = contrast;
    if (tex) r.facts.texture = true;
    if (["cone", "dome", "onion"].includes(style) && !r.facts.breaks && o.finial !== false) r.facts.breaks = 1;   // the finial over the ring course is the deliberate break
    const noEave = ["sawtooth", "dome", "onion"].includes(style) && !o.overhang;                                // no eave by design: on the record, not a warning
    const rev = review(r.facts, noEave ? { reasons: { overhang: `${style} has no eave by design`, ...(o.reasons || {}) } } : {});
    return { ...r, warnings: rev.warnings, lookNotes: rev.lookNotes };
  }
  const ovS = sidesOf(o.overhang ?? 1), ovVals = Object.values(ovS), ov = Math.max(...ovVals), uniform = ovVals.every((v) => v === ovVals[0]);
  const stone = !WOODS.has(mat.prefix);
  const tone0 = (m) => colourOf(matOf(m).full) || [0, 0, 0];
  const defaults = {                                                          // stone roofs get spruce edges, wood roofs a lighter or darker timber
    fascia: stone ? "spruce" : "birch",
    soffit: stone ? "spruce" : mat.prefix === "oak" || mat.prefix === "spruce" ? "birch" : "oak",   // spec says oak under spruce; birch keeps the legacy reroof test (no oak left over) green
    verge: stone ? "dark_oak" : mat.prefix === "dark_oak" ? "spruce" : "dark_oak",
  };
  const E0 = o.edges && typeof o.edges === "object" ? o.edges : {};
  const edgesOn = o.edges !== false && ov >= 1 && style !== "flat-parapet";
  const E = { fascia: edgesOn && E0.fascia !== false && o.eave !== "cornice", soffit: edgesOn && E0.soffit !== false, barge: edgesOn && E0.barge !== false };
  const placed = { fascia: 0, soffit: 0, barge: 0 };
  const surf = new Map(), planes = new Map();                               // roof blocks by material; stair runs by course and facing
  const noteSurf = (m, b, x, yy, z) => {
    surf.set(m.full, (surf.get(m.full) || 0) + 1);
    if (b[1]?.shape === "straight" && b[1]?.half === "bottom" && /_stairs$/.test(b[0])) { const key = `${yy}|${b[1].facing}`; (planes.get(key) || planes.set(key, new Set()).get(key)).add(K(x, z)); }
  };
