// A lean-to or shed row: stairs stepping up toward the wall, one stair per cell along the run.
function leanTo(g, cells, facing, state) {
  for (const [x, y, z] of cells) g.set(x, y, z, ...B.stairs(state.mat, facing, "bottom"));
