    if (xa > xb || za > zb) break;
    for (let x = xa; x <= xb; x++) {
      g.set(x, y + r, za, ...B.stairs(mat, "south", "bottom"));
      g.set(x, y + r, zb, ...B.stairs(mat, "north", "bottom"));
    }
    for (let z = za + 1; z <= zb - 1; z++) {
      g.set(xa, y + r, z, ...B.stairs(mat, "east", "bottom"));
